<?php
require_once __DIR__ . '/includes/session_bootstrap.php';
startVfnWebSession();
require_once __DIR__ . '/execute/config.php';
require_once __DIR__ . '/includes/language.php';
require_once __DIR__ . '/includes/web_session.php';
require_once __DIR__ . '/includes/ratings.php';
require_once __DIR__ . '/includes/atc_permissions.php';

$pdo = new PDO(
    "mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4",
    $dbUser,
    $dbPass,
    [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
);

$user = null;
if (!empty($_SESSION['web_user_id']) && validateVfnWebSession($pdo)) {
    $stmt = $pdo->prepare(
        "SELECT id, username, real_name, rating_atc, rating_special, op_permission
         FROM users WHERE id = :id LIMIT 1"
    );
    $stmt->execute(['id' => (int)$_SESSION['web_user_id']]);
    $user = $stmt->fetch(PDO::FETCH_ASSOC) ?: null;
}

$rating = (int)($user['rating_atc'] ?? 0);
$specialRating = (int)($user['rating_special'] ?? 0);
$ratingInfo = getAtcRating($rating);
$specialRatingInfo = getSpecialRating($specialRating);
$positions = getAtcPositionPermissions($rating, $specialRating);
$canControl = $user !== null && canUseAtcClient($rating, $specialRating);
$atcAccessAllowed = !empty($atcLoginEnabled) || (int)($user['op_permission'] ?? 0) >= 5;
$canOpen = $user !== null && $atcAccessAllowed;
$voiceSessionToken = '';
if ($user && $canOpen) {
    try {
        $voiceSessionToken = (string)($_SESSION['web_voice_token'] ?? '');
        if ($voiceSessionToken !== '') {
            $voiceCheck = $pdo->prepare("SELECT token FROM user_sessions WHERE user_id=:uid AND token=:token AND is_active=1 LIMIT 1");
            $voiceCheck->execute(['uid'=>(int)$user['id'],'token'=>$voiceSessionToken]);
            $voiceSessionToken = (string)($voiceCheck->fetchColumn() ?: '');
        }
        if ($voiceSessionToken === '') {
            $voiceSessionToken = bin2hex(random_bytes(32));
            $voiceInsert = $pdo->prepare("INSERT INTO user_sessions (user_id,token,callsign,is_active,is_invisible,is_spectator) VALUES (:uid,:token,:callsign,1,1,1)");
            $voiceInsert->execute(['uid'=>(int)$user['id'],'token'=>$voiceSessionToken,'callsign'=>'ATCWEB'.(int)$user['id']]);
            $_SESSION['web_voice_token']=$voiceSessionToken;
        }
    } catch (Throwable $error) { $voiceSessionToken=''; }
}
?>
