let selectedMode='',selectedPosition='',selectedStation=null,searchTimer=null,searchController=null,searchSequence=0;const atcPanel=document.getElementById('atcSetupWindow');const station=document.getElementById('station');const next=document.getElementById('continueButton');const results=document.getElementById('stationResults');const details=document.getElementById('stationDetails');const selectionArea=document.getElementById('selectionArea');const selectionHint=document.getElementById('selectionHint');
const ATC_VOICE_TOKEN=<?php echo json_encode($voiceSessionToken); ?>;const ATC_VOICE_URL=<?php echo json_encode((string)($voiceServiceWebSocketUrl ?? ''), JSON_UNESCAPED_SLASHES); ?>||((location.protocol==='https:'?'wss://':'ws://')+location.hostname+':8090');let currentAtcSession=null,radarMap=null,radarTrafficLayer=null,radarFirLayer=null,atcHeartbeatPoll=null,atcTrafficPoll=null,atcChatPoll=null,atcChatSinceId=0,atcChatFrequencyValue='',atcChatRequestInFlight=false,atcVoiceSocket=null,atcVoiceConnected=false,voicePlaybackContext=null,voicePlaybackTime=0,atcMicStream=null,atcMicContext=null,atcMicProcessor=null,atcMicSource=null,atcMicGain=null,atcVoiceSequence=0,radarContextTarget=null,initialContactCallsign='';const radarTargets=new Map(),radarLabelOffsets=new Map(),atcChatRenderedIds=new Set();const atcChatFrequency=document.getElementById('atcChatFrequency'),atcChatLog=document.getElementById('atcChatLog'),atcChatForm=document.getElementById('atcChatForm'),atcChatMessage=document.getElementById('atcChatMessage'),atcChatSend=document.getElementById('atcChatSend'),atcChatNote=document.getElementById('atcChatNote');
function initializeRadarMap(){if(radarMap)return;radarMap=L.map('atcRadarMap',{zoomControl:true,worldCopyJump:false,maxBoundsViscosity:1}).setView([51,10],6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap · VFN'}).addTo(radarMap);radarTrafficLayer=L.layerGroup().addTo(radarMap);radarMap.on('zoomend',()=>{refreshRadarTargetGeometry();refreshRadarTrails();});}
function airportRadarLimits(session,center){const profile=String(session.map_profile||'');const settings={airport_info:{radius:12,min:11,max:19,zoom:14},airport_delivery:{radius:10,min:12,max:19,zoom:15},airport_ground:{radius:8,min:13,max:19,zoom:16},airport_tower:{radius:45,min:9,max:19,zoom:11},terminal_approach:{radius:150,min:7,max:19,zoom:9},terminal_departure:{radius:150,min:7,max:19,zoom:9}}[profile];if(!settings||!center)return null;const latitude=Number(center.latitude),longitude=Number(center.longitude),latDelta=settings.radius/60,lonDelta=settings.radius/(60*Math.max(.2,Math.cos(latitude*Math.PI/180)));return{bounds:L.latLngBounds([latitude-latDelta,longitude-lonDelta],[latitude+latDelta,longitude+lonDelta]),min:settings.min,max:settings.max,zoom:settings.zoom};}
function applyAirportRadarLimits(session,center){const limits=airportRadarLimits(session,center);if(!limits)return;radarMap.setMinZoom(limits.min);radarMap.setMaxZoom(limits.max);radarMap.setMaxBounds(limits.bounds);if(!radarMap.__vfnCentered){radarMap.setView([Number(center.latitude),Number(center.longitude)],limits.zoom);radarMap.__vfnCentered=true;}}
function renderActivePositions(items){const list=document.getElementById('activePositionList');list.innerHTML='';if(!items.length){list.innerHTML='<div class="radar-empty">–</div>';return;}items.forEach(item=>{const row=document.createElement('div');row.className='active-position-row';row.innerHTML='<strong>'+escapeText(item.callsign)+'</strong><br><span'+(Number(item.is_spectator)?' class="spec"':'')+'>'+escapeText(item.position_code)+(Number(item.is_spectator)?' · SPEC':'')+'</span><br><span class="spec">'+escapeText(item.controller_name||'–')+'</span>';list.appendChild(row);});}
function normalizeAtcFrequency(value){const match=String(value||'').trim().replace(',','.').match(/^(\d{3})(?:\.(\d{0,3}))?$/);return match?match[1]+'.'+String(match[2]||'').padEnd(3,'0').slice(0,3):'';}
let atisAirports=[],selectedAtisAirport='',atisReloadTimer=null;
const atisChannel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('vfn-atc-atis'):null;
function atisPanelAvailable(session){return Boolean(session)&&!Number(session.is_spectator||session.spectator);}
function ensureAtisSelector(){
    const form=document.getElementById('atcAtisForm');let select=document.getElementById('atcAtisAirport');
    if(select)return select;
    const row=document.createElement('div');row.className='atis-selector-row';
    select=document.createElement('select');select.id='atcAtisAirport';select.setAttribute('aria-label','ATIS airport');
    const popupButton=document.createElement('button');popupButton.type='button';popupButton.className='window-action';popupButton.id='atcAtisNewWindow';popupButton.textContent='＋';popupButton.title='ATIS in neuem Fenster öffnen';
    row.append(select,popupButton);form.parentElement.insertBefore(row,form);
    let hidden=form.elements.airport;if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name='airport';form.prepend(hidden);}
    select.addEventListener('change',()=>selectAtisAirport(select.value));
    popupButton.addEventListener('click',()=>{if(!selectedAtisAirport)return;const id='vfn_atis_'+selectedAtisAirport+'_'+Date.now();window.open('atc_atis_window.php?airport='+encodeURIComponent(selectedAtisAirport),id,'popup=yes,width=560,height=720,resizable=yes,scrollbars=yes');});
    return select;
}
function storeAtisDraft(){
    if(!selectedAtisAirport)return;const form=document.getElementById('atcAtisForm'),draft={};
    ['arrival_runways','departure_runways','transition_level','transition_altitude','approach_type','remarks'].forEach(name=>draft[name]=form.elements[name]?.value||'');
    sessionStorage.setItem('vfn-atc-atis-draft-'+selectedAtisAirport,JSON.stringify(draft));
}
async function selectAtisAirport(airport){
    if(selectedAtisAirport&&selectedAtisAirport!==airport)storeAtisDraft();
    selectedAtisAirport=String(airport||'').toUpperCase();localStorage.setItem('vfn-atc-last-atis',selectedAtisAirport);
    const form=document.getElementById('atcAtisForm');if(form.elements.airport)form.elements.airport.value=selectedAtisAirport;
    await loadAtisSettings(false);
}
function renderAtisSettings(data){
    const form=document.getElementById('atcAtisForm'),settings=data.settings||{},broadcast=data.broadcast||null;
    let draft=null;try{draft=JSON.parse(sessionStorage.getItem('vfn-atc-atis-draft-'+selectedAtisAirport)||'null');}catch(error){}
    ['arrival_runways','departure_runways','transition_level','transition_altitude','approach_type','remarks'].forEach(name=>{if(form.elements[name])form.elements[name].value=draft?.[name]??settings[name]??'';});
    const airport=atisAirports.find(item=>item.icao===selectedAtisAirport)||{};const editable=Number(airport.editable)!==0;
    form.querySelectorAll('input:not([type="hidden"]),textarea,button').forEach(item=>item.disabled=!editable);
    const mode=Number(settings.is_active)?<?php echo json_encode(t('atc_atis_manual')); ?>:<?php echo json_encode(t('atc_atis_auto')); ?>;
    const details=broadcast?['<?php echo addslashes(t('atc_atis_current')); ?>: '+(broadcast.info_letter||'–'),broadcast.frequency?broadcast.frequency+' MHz':'',broadcast.active_runway?'RWY '+broadcast.active_runway:''].filter(Boolean).join(' · '):'';
    const manager=airport.managed_by?'\nDurch '+airport.managed_position+' · '+airport.managed_by+' verwaltet':'';
    document.getElementById('atcAtisStatus').textContent=(data.airport||'')+' · '+mode+(details?'\n'+details:'')+manager;
}
async function loadAtisAirports(){
    const panel=document.getElementById('atcAtisPanel'),available=atisPanelAvailable(currentAtcSession);panel.hidden=!available;
    if(!available){document.getElementById('atcAtisStatus').textContent=<?php echo json_encode(t('atc_atis_not_available')); ?>;return;}
    const select=ensureAtisSelector();const response=await fetch('execute/atc_atis_airports.php',{cache:'no-store'}),data=await response.json();
    if(!response.ok||!data.success)throw new Error(data.message||'atis_airports_failed');atisAirports=Array.isArray(data.airports)?data.airports:[];select.innerHTML='';
    atisAirports.forEach(item=>{const option=document.createElement('option');option.value=item.icao;option.textContent=item.icao+' · '+item.frequency+' · '+(item.info_letter||'ATIS')+(item.managed_by?' · '+item.managed_position:'');select.appendChild(option);});
    const preferred=[selectedAtisAirport,localStorage.getItem('vfn-atc-last-atis'),currentAtcSession?.station_code,atisAirports[0]?.icao].find(code=>atisAirports.some(item=>item.icao===code));
    if(!preferred){selectedAtisAirport='';document.getElementById('atcAtisStatus').textContent=<?php echo json_encode(t('atc_atis_not_available')); ?>;return;}
    select.value=preferred;selectedAtisAirport=preferred;const form=document.getElementById('atcAtisForm');if(form.elements.airport)form.elements.airport.value=preferred;await loadAtisSettings(false);
}
async function loadAtisSettings(refreshAirports=true){
    if(refreshAirports)return loadAtisAirports();if(!selectedAtisAirport)return;
    try{const response=await fetch('execute/atc_atis_settings.php?airport='+encodeURIComponent(selectedAtisAirport),{cache:'no-store'}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'atis_load_failed');renderAtisSettings(data);}catch(error){document.getElementById('atcAtisStatus').textContent=error.message;}
}
async function saveAtisSettings(action='save'){
    const form=document.getElementById('atcAtisForm'),status=document.getElementById('atcAtisStatus'),body=new FormData(form);body.set('action',action);body.set('airport',selectedAtisAirport);form.querySelectorAll('button').forEach(button=>button.disabled=true);
    try{const response=await fetch('execute/atc_atis_settings.php',{method:'POST',body}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'atis_save_failed');sessionStorage.removeItem('vfn-atc-atis-draft-'+selectedAtisAirport);renderAtisSettings(data);status.textContent=(action==='automatic'?<?php echo json_encode(t('atc_atis_auto_saved')); ?>:<?php echo json_encode(t('atc_atis_saved')); ?>)+'\n'+status.textContent;atisChannel?.postMessage({type:'updated',airport:selectedAtisAirport});clearTimeout(atisReloadTimer);atisReloadTimer=setTimeout(()=>loadAtisSettings(true),35000);}catch(error){status.textContent=error.message;}finally{form.querySelectorAll('button').forEach(button=>button.disabled=false);}
}
atisChannel?.addEventListener('message',event=>{if(event.data?.type==='updated'&&event.data.airport===selectedAtisAirport)loadAtisSettings(true);});
function setSessionDisplay(session){const previousCallsign=currentAtcSession?.callsign||'';currentAtcSession=session;document.getElementById('radarCallsign').textContent=session.callsign||'–';document.getElementById('radarStation').textContent=(session.station_code||'–')+' / '+(session.position_code||'–');document.getElementById('radarScope').textContent=Array.isArray(session.scope_positions)?session.scope_positions.join(', '):String(session.scope_positions||'').split(',').join(', ');document.getElementById('radarMapProfile').textContent=session.map_profile||'–';const frequencyInput=document.getElementById('atcVoiceFrequency');const selectedFrequency=previousCallsign===session.callsign?normalizeAtcFrequency(frequencyInput.value):'';const frequencyList=document.getElementById('atcVoiceFrequencyList');frequencyList.innerHTML='';(session.available_frequencies||[]).forEach(item=>{const option=document.createElement('option');option.value=normalizeAtcFrequency(item.frequency||'');option.label=(item.callsign||'')+(item.source?' · '+item.source:'');frequencyList.appendChild(option);});frequencyInput.value=selectedFrequency||normalizeAtcFrequency(session.frequency||((session.available_frequencies||[])[0]?.frequency)||'');document.getElementById('atcVoiceReference').value=session.station_code||'';document.getElementById('atcVoicePtt').hidden=Number(session.is_spectator||session.spectator)?true:false;}
async function loadRadarMaterial(session){
    initializeRadarMap();
    radarMap.__vfnCentered=false;
    radarMap.setMinZoom(2);
    radarMap.setMaxZoom(19);
    radarMap.setMaxBounds([[-85,-180],[85,180]]);
    if(radarFirLayer){radarFirLayer.remove();radarFirLayer=null;}
    const position=String(session.position_code||'').toUpperCase();
    try{
        let response=null;
        let filter=null;
        if(position==='CTR'){
            const station=String(session.station_code||'').toUpperCase();
            const detailedResponse=await fetch(
                'execute/sector_boundaries.php?station='+encodeURIComponent(station)
            );
            if(detailedResponse.ok){
                const detailed=await detailedResponse.json();
                radarFirLayer=L.geoJSON(detailed.geojson||{type:'FeatureCollection',features:[]},{
                    style:{color:'#78ff91',weight:2,fillColor:'#123b1d',fillOpacity:.16}
                }).addTo(radarMap);
            }else{
                response=await fetch('execute/fir_boundaries.php');
                const fallback=String(session.radar_boundary_code||'').toUpperCase();
                if(!response.ok)throw new Error('Boundary data unavailable');
                const geo=await response.json();
                const geoHasExactSector=(geo.features||[]).some(feature=>
                    String(feature.properties?.id||'').toUpperCase()===station
                );
                filter=feature=>{
                    const id=String(feature.properties?.id||'').toUpperCase();
                    return id===station||(!geoHasExactSector&&id===fallback);
                };
                radarFirLayer=L.geoJSON(geo,{
                    filter:filter,
                    style:{
                        color:geoHasExactSector?'#78ff91':'#a89070',weight:2,
                        fillColor:geoHasExactSector?'#123b1d':'#302a20',
                        fillOpacity:geoHasExactSector ? .16 : .05,
                        dashArray:geoHasExactSector?null:'3 8'
                    }
                }).addTo(radarMap);
                response=null;
            }
        }else if(position==='APP'||position==='DEP'){
            response=await fetch('execute/tracon_boundaries.php');
            const station=String(session.station_code||'').toUpperCase();
            filter=feature=>{
                const properties=feature.properties||{};
                const prefixes=Array.isArray(properties.prefix)?properties.prefix:[properties.prefix];
                const suffix=String(properties.suffix||'APP').toUpperCase();
                return prefixes.some(prefix=>String(prefix||'').toUpperCase()===station)&&suffix===position;
            };
        }
        if(response){
            if(!response.ok)throw new Error('Boundary data unavailable');
            const geo=await response.json();
            radarFirLayer=L.geoJSON(geo,{filter:filter,style:{
                color:'#78ff91',weight:2,fillColor:'#123b1d',fillOpacity:.16
            }}).addTo(radarMap);
        }
        if(radarFirLayer&&radarFirLayer.getLayers().length){
            const bounds=radarFirLayer.getBounds().pad(.18);
            radarMap.fitBounds(bounds,{padding:[30,30]});
            const fittedZoom=radarMap.getZoom();
            radarMap.setMinZoom(Math.max(2,fittedZoom-1));
            radarMap.setMaxZoom(19);
            radarMap.setMaxBounds(bounds);
            radarMap.__vfnCentered=true;
        }
    }catch(error){console.error(error);}
    setTimeout(()=>radarMap.invalidateSize(),80);
}
async function pollAtcHeartbeat(){try{const response=await fetch('execute/atc_heartbeat.php',{cache:'no-store'});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'heartbeat_failed');setSessionDisplay(data.session);renderActivePositions(Array.isArray(data.active_positions)?data.active_positions:[]);}catch(error){clearInterval(atcHeartbeatPoll);clearInterval(atcTrafficPoll);clearInterval(atcChatPoll);document.getElementById('radarCallsign').textContent=error.message;if(error.message==='atc_session_inactive'||error.message==='atc_login_disabled')setTimeout(()=>window.location.reload(),250);}}
