atcChatFrequency.addEventListener('change',()=>pollAtcChat(true));
atcChatForm.addEventListener('submit',async event=>{event.preventDefault();const frequency=normalizeAtcFrequency(atcChatFrequency.value),message=atcChatMessage.value.trim();if(!frequency||!message||atcChatSend.disabled)return;atcChatSend.disabled=true;try{const body=new URLSearchParams({frequency,message}),response=await fetch('execute/atc_chat.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body}),data=await response.json();if(!response.ok||!data.success)throw new Error(typeof data.message==='string'?data.message:'chat_send_failed');if(data.message){appendAtcChatMessage(data.message);atcChatSinceId=Math.max(atcChatSinceId,Number(data.message.id||0));}if(data.open_url)window.open(data.open_url,'_blank','noopener');atcChatMessage.value='';atcChatMessage.focus();await pollAtcChat();}catch(error){atcChatNote.hidden=false;atcChatNote.textContent=String(error.message||error);}finally{atcChatSend.disabled=false;}});
function enterRadar(session){atcPanel.__dockAtcWindow?.();atcPanel.hidden=true;const desk=document.getElementById('radarDesk');desk.hidden=false;document.getElementById('logoutAtcPositionButton').hidden=false;setSessionDisplay(session);atcChatFrequency.value=normalizeAtcFrequency(session.frequency||'')||'122.800';atcChatSend.disabled=Boolean(Number(session.is_spectator||session.spectator));atcChatMessage.disabled=atcChatSend.disabled;atcChatNote.hidden=!atcChatSend.disabled;loadRadarMaterial(session);loadAtisSettings();clearInterval(atcHeartbeatPoll);clearInterval(atcTrafficPoll);clearInterval(atcChatPoll);pollAtcHeartbeat();pollAtcTraffic();pollAtcChat(true);atcHeartbeatPoll=setInterval(pollAtcHeartbeat,5000);atcTrafficPoll=setInterval(pollAtcTraffic,3000);atcChatPoll=setInterval(pollAtcChat,2000);window.focus();}
async function logoutAtcPosition(){const button=document.getElementById('logoutAtcPositionButton');button.disabled=true;try{await setAtcPtt(false);}catch(error){}if(atcVoiceSocket){try{atcVoiceSocket.close();}catch(error){}atcVoiceSocket=null;}clearInterval(atcHeartbeatPoll);clearInterval(atcTrafficPoll);clearInterval(atcChatPoll);atcHeartbeatPoll=null;atcTrafficPoll=null;atcChatPoll=null;atcChatSinceId=0;atcChatLog.innerHTML='';try{await fetch('execute/atc_session_stop.php',{method:'POST',keepalive:true});}catch(error){}for(const popup of Array.from(detachedAtcWindows)){try{popup.close();}catch(error){}}Array.from(radarTargets.keys()).forEach(removeRadarTarget);radarLabelOffsets.clear();currentAtcSession=null;document.getElementById('radarDesk').hidden=true;button.hidden=true;button.disabled=false;atcPanel.hidden=false;atcPanel.__dockAtcWindow?.();selectedMode='';selectedPosition='';selectedStation=null;selectionArea.hidden=true;station.value='';details.hidden=true;results.hidden=true;atcPanel.querySelectorAll('.mode-button').forEach(item=>item.classList.remove('selected'));atcPanel.querySelectorAll('.position').forEach(item=>{item.classList.remove('selected','allowed');item.classList.add('locked');item.disabled=true;});update();}
function decodeAtcPcm(base64){const binary=atob(base64),samples=new Float32Array(Math.floor(binary.length/2));for(let i=0;i<samples.length;i++){let value=binary.charCodeAt(i*2)|(binary.charCodeAt(i*2+1)<<8);if(value>=32768)value-=65536;samples[i]=value/32768;}return samples;}
function encodeAtcPcm(samples){const bytes=new Uint8Array(samples.length*2),view=new DataView(bytes.buffer);for(let i=0;i<samples.length;i++){const sample=Math.max(-1,Math.min(1,samples[i]));view.setInt16(i*2,sample<0?sample*32768:sample*32767,true);}let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary);}
function downsampleAtc(input,inputRate,outputRate=16000){if(outputRate>=inputRate)return new Float32Array(input);const ratio=inputRate/outputRate,result=new Float32Array(Math.max(1,Math.round(input.length/ratio)));for(let i=0;i<result.length;i++){const start=Math.floor(i*ratio),end=Math.min(input.length,Math.floor((i+1)*ratio));let sum=0,count=0;for(let j=start;j<end;j++){sum+=input[j];count++;}result[i]=count?sum/count:0;}return result;}
async function playAtcVoice(payload){if(payload.codec!=='pcm16'||typeof payload.payload!=='string')return;const samples=decodeAtcPcm(payload.payload);voicePlaybackContext=voicePlaybackContext||new(window.AudioContext||window.webkitAudioContext)();if(voicePlaybackContext.state==='suspended')await voicePlaybackContext.resume();const buffer=voicePlaybackContext.createBuffer(1,samples.length,Number(payload.sampleRate||16000));buffer.copyToChannel(samples,0);const source=voicePlaybackContext.createBufferSource();source.buffer=buffer;source.connect(voicePlaybackContext.destination);if(voicePlaybackTime<voicePlaybackContext.currentTime||voicePlaybackTime>voicePlaybackContext.currentTime+.75)voicePlaybackTime=voicePlaybackContext.currentTime+.04;source.start(voicePlaybackTime);voicePlaybackTime+=buffer.duration;}
function connectAtcVoice(){const state=document.getElementById('atcVoiceState');const frequency=normalizeAtcFrequency(document.getElementById('atcVoiceFrequency').value);const reference=document.getElementById('atcVoiceReference').value.trim().toUpperCase();document.getElementById('atcVoiceFrequency').value=frequency;if(!ATC_VOICE_TOKEN||!frequency||(frequency!=='122.800'&&!reference)){state.textContent='<?php echo addslashes(t('atc_voice_disconnected')); ?>';return;}if(atcVoiceSocket)atcVoiceSocket.close();atcVoiceSocket=new WebSocket(ATC_VOICE_URL);atcVoiceSocket.addEventListener('open',()=>atcVoiceSocket.send(JSON.stringify({type:'hello',token:ATC_VOICE_TOKEN,callsign:currentAtcSession.callsign,com1:frequency,com2:frequency,txCom:1})));atcVoiceSocket.addEventListener('message',event=>{let payload;try{payload=JSON.parse(event.data);}catch(error){return;}if(payload.type==='hello'&&payload.success){atcVoiceConnected=true;atcVoiceSocket.send(JSON.stringify({type:'monitor',frequency,global:frequency==='122.800',airportIcao:frequency==='122.800'?'':reference,rangeNm:50}));}if(payload.type==='monitor'&&payload.success)state.textContent='<?php echo addslashes(t('atc_voice_connected')); ?>'+(Number(payload.receiveOnly)?' · <?php echo addslashes(t('atc_voice_receive_only')); ?>':'');if(payload.type==='audio')playAtcVoice(payload).catch(()=>{});if(payload.type==='error')state.textContent=String(payload.message||'Voice error');});atcVoiceSocket.addEventListener('close',()=>{atcVoiceConnected=false;state.textContent='<?php echo addslashes(t('atc_voice_disconnected')); ?>';});}
async function setAtcPtt(active){if(Number(currentAtcSession?.is_spectator||currentAtcSession?.spectator))return;if(!atcVoiceConnected)connectAtcVoice();if(active){atcMicStream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true},video:false});atcMicContext=atcMicContext||new(window.AudioContext||window.webkitAudioContext)();await atcMicContext.resume();atcMicSource=atcMicContext.createMediaStreamSource(atcMicStream);atcMicProcessor=atcMicContext.createScriptProcessor(2048,1,1);atcMicGain=atcMicContext.createGain();atcMicGain.gain.value=0;atcMicProcessor.onaudioprocess=event=>{if(!atcVoiceConnected)return;const frequency=document.getElementById('atcVoiceFrequency').value.trim();atcVoiceSocket.send(JSON.stringify({type:'audio',codec:'pcm16',sampleRate:16000,frequency,sequence:++atcVoiceSequence,ptt:true,payload:encodeAtcPcm(downsampleAtc(event.inputBuffer.getChannelData(0),atcMicContext.sampleRate))}));};atcMicSource.connect(atcMicProcessor);atcMicProcessor.connect(atcMicGain);atcMicGain.connect(atcMicContext.destination);atcVoiceSocket?.send(JSON.stringify({type:'ptt',active:true,txCom:1,frequency:document.getElementById('atcVoiceFrequency').value.trim()}));}else{atcVoiceSocket?.send(JSON.stringify({type:'ptt',active:false,txCom:1,frequency:document.getElementById('atcVoiceFrequency').value.trim()}));if(atcMicProcessor){atcMicProcessor.disconnect();atcMicProcessor=null;}if(atcMicSource){atcMicSource.disconnect();atcMicSource=null;}if(atcMicStream){atcMicStream.getTracks().forEach(track=>track.stop());atcMicStream=null;}}}
document.getElementById('atcVoiceConnect').addEventListener('click',connectAtcVoice);
document.getElementById('atcVoiceFrequency').addEventListener('blur',function(){this.value=normalizeAtcFrequency(this.value);});
document.getElementById('atcVoiceFrequency').addEventListener('keydown',function(event){if(event.key==='Enter'){event.preventDefault();connectAtcVoice();}});
document.getElementById('atcAtisForm').addEventListener('submit',event=>{event.preventDefault();saveAtisSettings('save');});
document.getElementById('atcAtisAutomatic').addEventListener('click',()=>saveAtisSettings('automatic'));
const atcPttButton=document.getElementById('atcVoicePtt');atcPttButton.addEventListener('pointerdown',()=>setAtcPtt(true).catch(()=>{}));['pointerup','pointercancel','pointerleave'].forEach(type=>atcPttButton.addEventListener(type,()=>setAtcPtt(false).catch(()=>{})));
function update(){next.disabled=!selectedPosition||!selectedStation;}
function escapeText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function chooseStation(item){selectedStation=item;station.value=item.code;results.hidden=true;details.hidden=false;details.innerHTML='<strong>'+escapeText(item.code)+'</strong> · '+escapeText(item.name)+(item.municipality?' · '+escapeText(item.municipality):'')+'<br><small>'+escapeText(item.kind_label)+(item.operation_label?' · '+escapeText(item.operation_label):'')+'</small>';const eligible=Array.isArray(item.eligible_positions)?item.eligible_positions:[];atcPanel.querySelectorAll('.position').forEach(button=>{const rankAllowed=selectedMode==='spectator'||button.dataset.rankAllowed==='1';const usable=rankAllowed&&eligible.includes(button.dataset.code);button.disabled=!usable;button.classList.toggle('allowed',usable);button.classList.toggle('locked',!usable);if(!usable&&button.classList.contains('selected')){button.classList.remove('selected');selectedPosition='';}});update();station.focus();}
async function searchStations(){const query=station.value.trim();const sequence=++searchSequence;if(searchController)searchController.abort();searchController=new AbortController();selectedStation=null;details.hidden=true;update();if(query.length<2){results.hidden=true;return;}try{const response=await fetch('execute/atc_station_search.php?q='+encodeURIComponent(query)+'&spectator='+(selectedMode==='spectator'?'1':'0'),{signal:searchController.signal});const data=await response.json();if(sequence!==searchSequence)return;if(!response.ok||!data.success)throw new Error(data.message||'search_failed');const items=Array.isArray(data.items)?data.items:[];const exact=items.find(item=>String(item.code).toUpperCase()===query.toUpperCase());if(exact&&items.length===1){chooseStation(exact);return;}results.innerHTML='';items.forEach(item=>{const button=document.createElement('button');button.type='button';button.className='station-result';button.innerHTML='<strong>'+escapeText(item.code)+'</strong> · '+escapeText(item.name)+'<small>'+escapeText(item.municipality||'')+' · '+escapeText(item.kind_label)+'</small>';button.addEventListener('mousedown',event=>{event.preventDefault();chooseStation(item);});results.appendChild(button);});if(items.length===0){results.innerHTML='<div class="station-result"><?php echo addslashes(t('atc_station_no_results')); ?></div>';}results.hidden=false;}catch(error){if(error.name==='AbortError'||sequence!==searchSequence)return;results.innerHTML='<div class="station-result"><?php echo addslashes(t('atc_station_search_error')); ?></div>';results.hidden=false;}}
function chooseMode(mode,button){selectedMode=mode;if(searchController)searchController.abort();++searchSequence;atcPanel.querySelectorAll('.mode-button').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');atcPanel.querySelectorAll('.supervision-note').forEach(item=>item.hidden=mode==='spectator');selectionArea.hidden=false;selectedPosition='';selectedStation=null;station.value='';details.hidden=true;results.hidden=true;atcPanel.querySelectorAll('.position').forEach(item=>{item.classList.remove('selected','allowed');item.classList.add('locked');item.disabled=true;});update();station.focus();}
document.getElementById('controllerMode')?.addEventListener('click',function(){chooseMode('controller',this);});
document.getElementById('spectatorMode').addEventListener('click',function(){chooseMode('spectator',this);});
station.addEventListener('input',function(){clearTimeout(searchTimer);searchTimer=setTimeout(searchStations,180);});
station.addEventListener('keydown',function(event){if(event.key==='Escape')results.hidden=true;if(event.key==='Enter'){event.preventDefault();const first=results.querySelector('button.station-result');if(first)first.dispatchEvent(new MouseEvent('mousedown',{bubbles:true}));}});
atcPanel.querySelectorAll('.position').forEach(button=>button.addEventListener('click',function(){if(this.disabled)return;atcPanel.querySelectorAll('.position').forEach(item=>item.classList.remove('selected'));this.classList.add('selected');selectedPosition=this.dataset.code;update();}));
next.addEventListener('click',async function(){next.disabled=true;try{const body=new URLSearchParams({station:selectedStation.code,position:selectedPosition,spectator:selectedMode==='spectator'?'1':'0'});const response=await fetch('execute/atc_session_start.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'session_failed');selectionHint.textContent=data.callsign+' – '+(data.spectator?'<?php echo addslashes(t('atc_spectator_ready')); ?>':'<?php echo addslashes(t('atc_position_ready')); ?>');enterRadar(data);}catch(error){selectionHint.textContent=error.message;}finally{update();}});
async function resumeAtcSession(){try{const response=await fetch('execute/atc_heartbeat.php',{cache:'no-store'});if(!response.ok)return;const data=await response.json();if(data.success&&data.session)enterRadar(data.session);}catch(error){}}
resumeAtcSession();
document.getElementById('logoutAtcPositionButton').addEventListener('click',logoutAtcPosition);
<?php endif; ?>
}
